<script setup lang="ts">
import {useNativeCard} from '../../business/controller';
const {business,result,readonly,context,roomId,description,note,assigneeId,selectedIssueId,issueAction,busy,admin,issue,labels,dirty,prepare,transition,actions,actionLabels}=useNativeCard();
</script>
<template>
   <div v-if="result.view==='issues'">
    <form v-if="!readonly" class="native-form" @submit.prevent="prepare({kind:'issue.create',roomId,description})"><label>故障房间<select v-model="roomId" required><option v-for="r in context?.rooms||[]" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label class="wide">故障描述<textarea v-model="description" required rows="2" @input="dirty" placeholder="填写现场观察，尚未核实的内容请注明"></textarea></label><button :disabled="busy">准备真实工单</button></form>
    <div v-for="i in context?.issues||[]" :key="i.id" class="object-row"><b>{{i.id}} · {{labels[i.status]||i.status}} · v{{i.revision}}</b><p>{{i.description}} · 负责人 {{i.assigneeId||'未指派'}}</p><details><summary>处理历史</summary><p v-for="(h,n) in i.history||[]" :key="n">{{h.at}} · {{h.actorId}} · {{h.status==='awaiting_acceptance'?'交接待接收':labels[h.status]||h.status}} · {{h.note}}</p></details></div>
    <form v-if="!readonly&&(admin||context?.issues.some(i=>i.assigneeId===business.profile?.username))" class="native-form" @submit.prevent="transition"><label class="wide">处理工单<select aria-label="处理工单" v-model="selectedIssueId" required @change="issueAction=issue?actions(issue).at(0)||'':'';dirty()"><option value="">请选择</option><option v-for="i in (context?.issues||[]).filter(i=>actions(i).length&&(admin||i.assigneeId===business.profile?.username))" :key="i.id" :value="i.id">{{i.id}} · {{labels[i.status]||i.status}}</option></select></label><label v-if="issue">操作<select aria-label="操作" v-model="issueAction" @change="dirty"><option v-for="a in actions(issue)" :key="a" :value="a">{{actionLabels[a]}}</option></select></label><label v-if="issueAction==='assign'">负责人<select aria-label="负责人" v-model="assigneeId" required @change="dirty"><option value="">请选择</option><option v-for="u in context?.assignees||[]" :key="u.username" :value="u.username">{{u.username}}</option></select></label><label class="wide">处理 / 验收说明<textarea aria-label="处理 / 验收说明" v-model="note" required rows="2" @input="dirty"></textarea></label><button :disabled="busy||!issue">准备状态变更</button></form>
   </div>
</template>
